SELECT datetime, sum(trdePrc)trdePrc, sum(puchasPrc)puchasPrc, shopName FROM( select (select datetime from sale_off where sale_id = S.sale_id)datetime, (select shop_name from shop A, sale_off B where A.shop_id = B.shop_id AND B.sale_id = S.sale_id)shopName, sale_id, prdct_id, (select sum(trde_prc * S.prdct_cnt) from prdct where prdct_id = S.prdct_id) trdePrc, (select sum(puchas_prc * S.prdct_cnt) from prdct where prdct_id = S.prdct_id) puchasPrc from salePrdct_off S )y
WHERE datetime = #{toDay}
WHERE datetime >= #{yesterDay} AND datetime <= #{toDay}
WHERE datetime >= #{month} AND datetime <= #{toDay}
GROUP BY shopName ORDER BY trdePrc limit 10

SELECT (select staff_name from staff where staff_id = y.staff_id)staff_name, staff_id,
datetime , sum(prc) prc, avg(prc)staffSalesAvg FROM( select (select shop_id from staff where staff_id = S.staff_id)shop_id, (select staff_id from staff where staff_id = S.staff_id)staff_id , (select datetime from sale_off where sale_id = S.sale_id)datetime, (select prc from salePrdct_off where sale_id = S.sale_id GROUP BY sale_id)prc from sale_job_off S )y WHERE y.shop_id = #{shopId}
AND datetime = #{toDay}
AND datetime >= #{yesterDay} AND datetime <= #{toDay}
AND datetime >= #{month} AND datetime <= #{toDay}
GROUP BY staff_name ORDER BY prc DESC

SELECT y.start_time, y.staff_id, y.datetime, y.staff_name, (select count(Distinct start_time) from sale_job_off where ty_cd="01200001" AND datetime = y.datetime AND staff_id = #{staffId} group by datetime)selectPrdct, (select count(Distinct start_time) from sale_job_off where ty_cd="01200002" AND datetime = y.datetime AND staff_id = #{staffId} group by datetime)chkeyes, (select count(Distinct start_time) from sale_job_off where ty_cd="01200003" AND datetime = y.datetime AND staff_id = #{staffId} group by datetime)asmbly, (select count(Distinct start_time) from sale_job_off where ty_cd="01200004" AND datetime = y.datetime AND staff_id = #{staffId} group by datetime)payment, (select count(Distinct start_time) from sale_job_off where ty_cd="01200005" AND datetime = y.datetime AND staff_id = #{staffId} group by datetime)dlvl from( select start_time, datetime, (select staff_id from staff where staff_id = S.staff_id) staff_id, (select staff_name from staff where staff_id = S.staff_id) staff_name from sale_job_off S
WHERE datetime = #{toDay}
WHERE datetime >= #{yesterDay} AND datetime <= #{toDay}
WHERE datetime >= #{month} AND datetime <= #{toDay}
group by staff_id )y WHERE staff_id = #{staffId}
